import{_ as r,y as s,a,o as i,a2 as t,D as n}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"GDPR","description":"","frontmatter":{},"headers":[],"relativePath":"configure/gdpr.md","filePath":"configure/gdpr.md","lastUpdated":1789395222000}'),c={name:"configure/gdpr.md"};function g(h,e,l,d,u,p){const o=s("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="gdpr" tabindex="-1">GDPR <a class="header-anchor" href="#gdpr" aria-label="Permalink to &quot;GDPR&quot;">​</a></h1><p>Bagisto&#39;s GDPR (General Data Protection Regulation) features let customers request the personal data you hold about them, record their consent when they create an account, and show a cookie notice on the storefront. Every setting on this screen is set per channel and per language, so choose both at the top of the screen before you change anything.</p><p>Go to <strong>Configure &gt;&gt; General &gt;&gt; GDPR</strong>.</p><h2 id="turn-gdpr-on" tabindex="-1">Turn GDPR on <a class="header-anchor" href="#turn-gdpr-on" aria-label="Permalink to &quot;Turn GDPR on&quot;">​</a></h2><ol><li>In <strong>GDPR Compliance Settings</strong>, switch <strong>Enable GDPR</strong> on.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),n(o,{src:"/images/configure/gdpr-settings.png",alt:"GDPR Compliance Settings and GDPR Agreement sections with both switches turned on"}),e[1]||(e[1]=t('<p>When GDPR is on, customers find <strong>GDPR Data Requests</strong> in their account on the storefront, where they click <strong>Create Request</strong> to ask for their data to be updated or deleted. You handle the requests under <strong>Customers &gt;&gt; GDPR Data Requests</strong>.</p><h2 id="ask-for-consent-when-customers-sign-up" tabindex="-1">Ask for consent when customers sign up <a class="header-anchor" href="#ask-for-consent-when-customers-sign-up" aria-label="Permalink to &quot;Ask for consent when customers sign up&quot;">​</a></h2><p>The customer agreement adds a checkbox that customers must tick to create an account.</p><ol><li>In <strong>GDPR Agreement</strong>, switch <strong>Enable Customer Agreement</strong> on.</li><li>Enter the <strong>Agreement Checkbox Label</strong>, the sentence shown beside the checkbox. The default is <em>I agree with the terms and conditions.</em></li><li>Enter the <strong>Agreement Content</strong>, the full text of the agreement that customers can open from the checkbox.</li><li>Click <strong>Save Configuration</strong>.</li></ol><h2 id="show-a-cookie-notice" tabindex="-1">Show a cookie notice <a class="header-anchor" href="#show-a-cookie-notice" aria-label="Permalink to &quot;Show a cookie notice&quot;">​</a></h2><ol><li>In <strong>Cookie Notice Settings</strong>, switch <strong>Enable Cookie Notice</strong> on.</li><li>Choose the <strong>Cookie Block Display Position</strong>: <strong>Bottom Left</strong> (the default), <strong>Bottom Right</strong>, <strong>Top Left</strong>, <strong>Top Right</strong> or <strong>Center</strong>.</li><li>Enter the <strong>Static Block Identifier</strong>, the heading shown at the top of the notice. The default is <strong>Cookie Block</strong>.</li><li>Enter the <strong>Description</strong>, the message shoppers read in the notice, in up to 500 characters. A link to your privacy policy page is added after it.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',6)),n(o,{src:"/images/configure/gdpr-cookie-notice.png",alt:"Cookie Notice Settings section with the cookie notice turned on"}),e[2]||(e[2]=t('<h2 id="describe-the-cookie-categories" tabindex="-1">Describe the cookie categories <a class="header-anchor" href="#describe-the-cookie-categories" aria-label="Permalink to &quot;Describe the cookie categories&quot;">​</a></h2><p><strong>Manage Your Cookie Preferences</strong> holds the text shown for each type of cookie a shopper can allow. Each comes with default text that you can edit:</p><ul><li><strong>Strictly Necessary</strong> – cookies the storefront needs in order to work.</li><li><strong>Basic Interactions &amp; Functionalities</strong> – trackers behind basic interactions and features.</li><li><strong>Experience Enhancements</strong> – trackers that personalize the shopper&#39;s experience.</li><li><strong>Measurements</strong> – trackers that measure traffic and behavior.</li><li><strong>Targeting &amp; Advertising</strong> – trackers used for personalized marketing and ads.</li></ul><p>Click <strong>Save Configuration</strong> after changing any of them.</p>',4))])}const k=r(c,[["render",g]]);export{f as __pageData,k as default};
